function getCsrfToken(){const t=document.cookie.split(";").map(t=>t.trim()).find(t=>t.startsWith("csrf_token="));return t?decodeURIComponent(t.slice(11)):""}async function fetchWithCsrf(t,e={}){if(["POST","PUT","DELETE"].includes((e.method||"GET").toUpperCase())){e.headers=e.headers||{};const t=getCsrfToken();t&&(e.headers["X-CSRF-Token"]=t)}return fetch(t,{credentials:"same-origin",...e})}export const API_URL="/api/data";export const LOGIN_URL="/api/login";export const LOGOUT_URL="/api/logout";export const CHANGE_PIN_URL="/api/change-pin";export const PUSH_REGISTER_URL="/api/push/register";export const PUSH_UNREGISTER_URL="/api/push/unregister";export async function loadDataFromServer(){try{const t=await fetchWithCsrf("/api/data");if(t.ok)return await t.json()}catch(t){console.error("Failed to load from server:",t)}return null}export async function loadBaseData(){try{const t=await fetchWithCsrf("/api/base-data");if(t.ok)return await t.json()}catch(t){console.error("Failed to load base data:",t)}return{tasks:[],products:[]}}export async function saveDataToServer(t){try{const e=await fetchWithCsrf(API_URL,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(t)});if(!e.ok){let t="";try{const r=await e.clone().json();t=r?.error?`: ${r.error}`:""}catch(t){}console.error(`Failed to save data (${e.status})${t}`)}return e.ok}catch(t){return console.error("Failed to save to server:",t),!1}}export async function logout(){try{return(await fetchWithCsrf(LOGOUT_URL,{method:"POST"})).ok}catch(t){return console.error("Logout failed:",t),!1}}export async function registerPushTokenOnServer(t){try{const e=await fetchWithCsrf(PUSH_REGISTER_URL,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(t)});return e.ok?{success:!0}:await e.json()}catch(t){return{success:!1,error:"Network error"}}}export async function unregisterPushTokenOnServer(t){try{const e=await fetchWithCsrf(PUSH_UNREGISTER_URL,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({token:t})});return e.ok?{success:!0}:await e.json()}catch(t){return{success:!1,error:"Network error"}}}export async function changePin(t,e,r){try{const n=await fetchWithCsrf(CHANGE_PIN_URL,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({oldPin:t,newPin:e,role:r})});if(n.ok)return{success:!0};return{success:!1,error:(await n.json()).error}}catch(t){return{success:!1,error:"Ошибка сети"}}}export async function login(t){try{const e=await fetchWithCsrf(LOGIN_URL,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({pin:t})});if(e.ok){return{success:!0,role:(await e.json()).role}}return{success:!1,error:(await e.json()).error,status:e.status}}catch(t){return{success:!1,error:"Network Error"}}}export async function regenerateChildToken(t){try{const e=await fetchWithCsrf(`/api/children/${t}/regenerate-token`,{method:"POST"});if(e.ok)return await e.json()}catch(t){console.error("Failed to regenerate token:",t)}return null}export async function addChild(t){try{const e=await fetchWithCsrf("/api/children",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({name:t})});return await e.json()}catch(t){return{success:!1,error:"Network error"}}}export async function deleteChild(t){try{const e=await fetchWithCsrf(`/api/children/${t}`,{method:"DELETE"});return await e.json()}catch(t){return{success:!1,error:"Network error"}}}export async function getChildLink(t){try{const e=await fetchWithCsrf(`/api/children/${t}/link`);return await e.json()}catch(t){return{success:!1,error:"Network error"}}}export async function updateChildSettings(t,e,r){try{const t=await fetchWithCsrf(`/api/children/${e}/settings`,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(r)});return await t.json()}catch(t){return console.error("Failed to update child settings:",t),{success:!1,error:"Network error"}}}export async function updateNickname(t){try{const e=await fetchWithCsrf("/api/update-nickname",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({nickname:t})});return await e.json()}catch(t){return console.error("Failed to update nickname:",t),{success:!1,error:"Ошибка сети"}}}export async function searchUsers(t){try{const e=await fetchWithCsrf(`/api/search-user?nickname=${encodeURIComponent(t)}`);if(e.ok)return await e.json()}catch(t){console.error("Failed to search users:",t)}return[]}export async function addFriend(t){try{const e=await fetchWithCsrf("/api/add-friend",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({friendId:t})});return await e.json()}catch(t){return console.error("Failed to add friend:",t),{success:!1,error:"Ошибка сети"}}}export async function loadFriendsList(){try{const t=await fetchWithCsrf("/api/friends-list");if(t.ok)return await t.json()}catch(t){console.error("Failed to load friends list:",t)}return[]}export async function savePreference(t,e){try{return(await fetchWithCsrf("/api/preferences",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({[t]:e})})).ok}catch(t){return console.error("Failed to save preference:",t),!1}}export async function saveChildTheme(t,e){try{return(await fetchWithCsrf(`/api/children/${t}/theme`,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({theme:e})})).ok}catch(t){return console.error("Failed to save child theme:",t),!1}}export async function fetchAnalyticsData(t="month",e=null){try{let r=`/api/analytics?timeframe=${t}`;e&&(r+=`&childId=${e}`);const n=await fetchWithCsrf(r);if(n.ok)return await n.json()}catch(t){console.error("Failed to fetch analytics:",t)}return null}